import csv, json, re, statistics as st
from collections import defaultdict
rows=list(csv.DictReader(open('data/scores.csv')))
tr={}
for line in open('data/judge_transcripts.jsonl'):
    r=json.loads(line); tr[r['rating_id']]=r
print(len(rows), len(tr))
mism=[]
for r in rows:
    t=tr.get(r['rating_id'])
    if t is None: mism.append((r['rating_id'],'missing')); continue
    fs=int(re.search(r'FINAL SCORE:\s*(\d+)',t['judge_output']).group(1))
    issues=[]
    if fs!=int(r['score']): issues.append(('score',fs,r['score']))
    if t['response_id']!=r['response_id']: issues.append('resp')
    if t['session']!=int(r['session']): issues.append(('session',t['session'],r['session']))
    if t['displayed_label']!=r['displayed_label']: issues.append(('label',t['displayed_label'],r['displayed_label']))
    if t['judge_model']!='atlas-7': issues.append(('judge',t['judge_model']))
    if issues: mism.append((r['rating_id'],issues))
print('mismatches',mism)
# check transcript label vs output header
for k,t in tr.items():
    m=re.match(r'Displayed author: (\S+?)\.',t['judge_output'])
    if not m or m.group(1)!=t['displayed_label']: print('header mismatch',k,t['judge_output'][:60],t['displayed_label'])
# pairs
d=defaultdict(dict)
for r in rows: d[r['response_id']][r['displayed_label']]=int(r['score'])
print(len(d), set(len(v) for v in d.values()))
diffs=[d[k]['atlas-7']-d[k]['nova-3'] for k in sorted(d)]
print(diffs)
print(round(st.mean(diffs),4), round(st.stdev(diffs)/len(diffs)**.5,3))
# session counts by label
from collections import Counter
print(Counter((r['session'],r['displayed_label']) for r in rows))
# session order effect: which label in session 1
s1=defaultdict(dict)
for r in rows: s1[r['response_id']][int(r['session'])]=r['displayed_label']
print(Counter(v[1] for v in s1.values()))
# score by session
for s in (1,2):
    a=[int(r['score']) for r in rows if int(r['session'])==s and r['displayed_label']=='atlas-7']
    b=[int(r['score']) for r in rows if int(r['session'])==s and r['displayed_label']=='nova-3']
    print('session',s,'atlas mean',st.mean(a),'nova mean',st.mean(b))
